lesson(num=10, unit="B", title=B("Exam Power: Reading and Writing for Full Marks", "Poder de examen: lectura y escritura para sacar nota máxima"),
 intro=B("Know the 40-mark paper and exactly how each mark is earned.", "Conoce el examen de 40 puntos y cómo se gana cada punto."),
 ideas=[
  B("<b>The paper (40 marks, 55 minutes):</b> A Vocabulary 8 · B Grammar 10 · C At the shop 6 · D Reading 8 · E Writing 8. Plan about 40 to 45 minutes and keep the rest for checking.", "<b>El examen (40 puntos, 55 minutos):</b> A Vocabulario 8 · B Gramática 10 · C En la tienda 6 · D Lectura 8 · E Escritura 8. Calcula unos 40 a 45 minutos y deja el resto para revisar."),
  B("<b>Reading (D):</b> one mark per answer. A word or short phrase is enough, in English or Spanish. Look for the colour, material, number, country, place, weather and item. Spelling is not marked when the meaning is clear.", "<b>Lectura (D):</b> un punto por respuesta. Basta una palabra o frase corta, en inglés o español. Busca el color, material, número, país, lugar, tiempo y objeto. La ortografía no se califica si el significado es claro."),
  B("<b>Writing (E):</b> four short sentences, <b>2 marks each</b>: <b>1 for content</b> (the information asked) and <b>1 for language</b> (clear Spanish). Simple sentences earn full marks.", "<b>Escritura (E):</b> cuatro frases cortas, <b>2 puntos cada una</b>: <b>1 de contenido</b> (la información pedida) y <b>1 de lenguaje</b> (español claro). Las frases simples ganan puntos completos."),
  B("<b>Always write the full sentence.</b> A copied starter on its own earns no language mark. <i>Voy a ir a España con mi familia.</i>", "<b>Escribe siempre la frase completa.</b> Copiar solo el inicio no gana punto de lenguaje. <i>Voy a ir a España con mi familia.</i>"),
  B("<b>Lose the language mark by:</b> a wrong key verb form, a missing <b>a</b> in the near future, or a colour that does not agree with its noun. Accent slips alone do not cost marks.", "<b>Pierdes el punto de lenguaje por:</b> una forma verbal clave incorrecta, falta de <b>a</b> en el futuro próximo, o un color que no concuerda. Los acentos solos no restan."),
  B("<b>Your four-sentence formula:</b> 1) <i>Voy a ir a ... con ...</i> 2) <i>Hace ...</i> 3) <i>Llevo un/una ... + colour</i> 4) <i>Voy a + infinitive</i>.", "<b>Tu fórmula de cuatro frases:</b> 1) <i>Voy a ir a ... con ...</i> 2) <i>Hace ...</i> 3) <i>Llevo un/una ... + color</i> 4) <i>Voy a + infinitivo</i>."),
 ],
 table={"head": [B("Section", "Sección"), B("Marks", "Puntos"), B("What to revise", "Qué repasar")],
        "rows": [[B("A Vocabulary", "A Vocabulario"), S("8"), B("Lessons 1, 2 and 6", "Lecciones 1, 2 y 6")], [B("B Grammar", "B Gramática"), S("10"), B("Lessons 3, 4, 7 and 8", "Lecciones 3, 4, 7 y 8")], [B("C At the shop", "C En la tienda"), S("6"), B("Lesson 5", "Lección 5")], [B("D Reading", "D Lectura"), S("8"), B("Reading Lab", "Laboratorio de lectura")], [B("E Writing", "E Escritura"), S("8"), B("Writing Lab", "Laboratorio de escritura")]]},
 fact=B("Match your tense to the question. <i>Where are you going?</i> needs <b>voy a</b>. <i>Where did you go?</i> needs <b>fui a</b>.", "Ajusta el tiempo a la pregunta. <i>¿Adónde vas?</i> pide <b>voy a</b>. <i>¿Adónde fuiste?</i> pide <b>fui a</b>."),
 activities=[
  {"type": "answer", "title": B("Tick the true exam tips", "Marca los consejos de examen verdaderos"),
   "statements": [[B("Write a full sentence, not just the starter.", "Escribe una frase completa, no solo el inicio."), True], [B("Simple sentences can earn full marks.", "Las frases simples pueden ganar puntos completos."), True], [B("Content and language marks are awarded separately.", "Los puntos de contenido y de lenguaje se dan por separado."), True], [B("In reading, a short phrase in English is enough.", "En lectura basta una frase corta en inglés."), True], [B("Missing the 'a' in <i>voy a comer</i> loses the language mark for that sentence.", "Olvidar la «a» en <i>voy a comer</i> pierde el punto de lenguaje de esa frase."), True], [B("Long answers are required for full marks.", "Se necesitan respuestas largas para ganar todos los puntos."), False], [B("Copying the starter is enough.", "Copiar el inicio es suficiente."), False], [B("Accent slips always lose a mark.", "Un error de acento siempre quita un punto."), False]]},
 ],
 questions=[B("How many marks are in each of the four writing sentences and how are they split?", "¿Cuántos puntos vale cada una de las cuatro frases de escritura y cómo se reparten?"), B("Name two ways to lose the language mark.", "Nombra dos formas de perder el punto de lenguaje."), B("Is a short phrase enough in the reading section?", "¿Basta una frase corta en la sección de lectura?"), B("Which sections test grammar and how many marks are there in total?", "¿Qué sección evalúa la gramática y cuántos puntos hay en total?"), B("Write a full-mark answer to: say what the weather is like.", "Escribe una respuesta de puntos completos a: di qué tiempo hace.")],
 task=B("Time yourself: write your four writing sentences for a trip to Peru in under five minutes, then check each against the formula.", "Cronométrate: escribe tus cuatro frases de escritura para un viaje a Perú en menos de cinco minutos y compara cada una con la fórmula."),
 answers=[B("2 marks each: 1 content, 1 language.", "2 puntos cada una: 1 contenido, 1 lenguaje."), B("A wrong verb form, missing 'a' in near future, or colour not agreeing with the noun.", "Una forma verbal incorrecta, falta de «a» en futuro próximo o color que no concuerda con el sustantivo."), B("Yes. A word or short phrase is enough.", "Sí. Basta una palabra o frase corta."), B("Section B Grammar, 10 marks. The paper has 40 marks in total.", "Sección B Gramática, 10 puntos. El examen tiene 40 puntos en total."), S("Hace calor.")])
